import csv
import io
import json

_FIELDS = ("id", "name")


def _normalize(rows):
    """Return a new list of {"id": str, "name": str} records, in input order.

    Only the id and name fields are kept. Missing or None values become ''
    and every other value is converted with str(). Inputs are not mutated and
    one-shot iterables are consumed exactly once.
    """
    records = []
    for row in rows:
        records.append({
            key: "" if row.get(key) is None else str(row[key])
            for key in _FIELDS
        })
    return records


def _serialize_csv(records):
    buffer = io.StringIO(newline="")
    writer = csv.writer(buffer, lineterminator="\n")
    writer.writerow(_FIELDS)
    for record in records:
        writer.writerow([record[key] for key in _FIELDS])
    return buffer.getvalue()


def _serialize_json(records):
    return json.dumps(records, ensure_ascii=False, separators=(",", ":"))


_SERIALIZERS = {
    "csv": _serialize_csv,
    "json": _serialize_json,
}


def export_rows(rows, format):
    """Export rows as 'csv' or 'json' text.

    Raises ValueError for any other format. The format is checked before
    rows are read.
    """
    if not isinstance(format, str) or format not in _SERIALIZERS:
        raise ValueError("unsupported format")
    return _SERIALIZERS[format](_normalize(rows))
